action.mutation:
mutation CreateCertificationRequirement($payload: [CertificationRequirementCreatePayloadInput!]!) {
  mutation: createCertificationRequirement(payload: $payload) { 
    id
    id
  }
}

mutation UpdateCertificationRequirement($payload: [CertificationRequirementUpdatePayloadInput!]!) {
  mutation: updateCertificationRequirement(payload: $payload) { 
    id
    id
  }
}

mutation DeleteCertificationRequirement($payload: [CertificationRequirementDeletePayloadInput!]!) {
  mutation: deleteCertificationRequirement(payload: $payload) { 
    id
    id
  }
}
